"""Concise completion-therapy and procedural decisions."""
from cardiology_10_compact_diagnosis import B,S
edits={
'10-056':S('Localize the Embolic Source',[B('**Tricuspid or infected-lead vegetations seed the pulmonary circulation.**','Pleuritic pain, hemoptysis, peripheral nodules/cavities and wedge lesions support septic pulmonary emboli but are not individually diagnostic.'),B('**Cultures plus echocardiography:** assess catheters, devices, injection exposure and coexisting left-sided disease.')],
 'Treat Infection and Complications',[B('**Pathogen-directed therapy and source assessment**, not automatic therapeutic anticoagulation.','Evaluate empyema, abscess and respiratory failure; drain indicated collections.'),B('**Surgery review for persistent infection, severe valve-related RV dysfunction or recurrent embolic respiratory compromise.**','Vegetation size alone is insufficient; complications can exclude a short MSSA course.'),B('**Provide addiction care and practical treatment support** when relevant.')]),
'10-057':S('Selected Aspiration Role',[B('**Expert-center adjunctive source control** for selected refractory right-sided infection or prohibitive surgical risk.','Debulking may reduce infected mass; size alone is not an indication and left-sided evidence cannot be assumed.')],
 'Evidence and Limitations',[B('**No randomized trial establishes safety or efficacy.**','Observational results are vulnerable to selection; risks include bleeding, vascular injury, embolization, valve damage and incomplete removal.'),B('**Continue antibiotics, cultures and metastatic-focus assessment.**','Aspiration does not reliably repair severe regurgitation or replace complete extraction for infected CIEDs.'),B('**Do not claim superiority to feasible indicated surgery.**','Agree on escalation if bacteremia or hemodynamic failure persists.')]),
'10-058':S('Definite Pocket Involvement',[B('**Erosion, exposed generator or communicating sinus indicates pocket infection.**','Negative blood cultures and no visible lead vegetation do not exclude localized infection.'),B('**Superficial incision inflammation lacks pocket/hardware involvement.**','A skin-only process is a different treatment category.')],
 'Complete-System Plan',[B('**Remove generator and leads when feasible, with appropriate antimicrobials.**','Local closure or generator-only exchange leaves potentially infected connected material.'),B('**Assess extraction risk and obtain operative microbiology.**','Antibiotic duration depends on isolated pocket versus bacteremia, lead or valve involvement.'),B('**Reassess device need and replacement timing/site.**','Avoid automatic reimplantation into the infected pocket.')]),
'10-059':S('Remove the Infected Reservoir',[B('**Confirmed lead infection requires complete-system extraction when feasible.**','Antibiotics may suppress bloodstream growth without sterilizing biofilm.'),B('**Use an experienced extraction team with rescue capability.**','Lead age, anatomy, vegetation burden and valve-surgery needs influence approach.')],
 'Treatment After Extraction',[B('**Continue pathogen-directed therapy and clearance cultures.**','Duration follows organism, bacteremia, lead/valve involvement and complications; investigate metastatic sites.'),B('**Retention/suppression is an exception for genuinely prohibitive removal risk.**','Transient improvement does not establish cure with retained infected hardware.'),B('**Reassess permanent-device need; bridge rhythm support if required.**','Reimplant at a suitable distant site after clinical and microbiological control.')]),
'10-060':S('Negative TEE Does Not Exclude CIED Infection',[B('**Persistent S. aureus bacteremia remains concerning despite a normal pocket.**','Small/early lesions or extracardiac lead involvement may escape visualization.'),B('**Repeat cultures and review vascular access, device history and other sources.**','CRP or fever improvement does not establish clearance.')],
 'Resolve the Remaining Suspicion',[B('**Repeat echo and selected FDG-PET/CT can complement the first study.**','Negative PET does not universally exclude lead infection; a lead mass can also be noninfectious.'),B('**Consider extraction when confirmed infection or compelling unexplained persistence supports it.**','Integrate pathogen, alternative sources and procedural risk rather than requiring a visible vegetation.'),B('**Generator exchange is not a diagnostic substitute.**')]),
'10-061':S('Reassess Need and Bridge Safely',[B('**Confirm the ongoing permanent-device indication.**','Use appropriate temporary support if necessary; select a distant replacement site and suitable platform.')],
 'ESC 2023 Clearance Intervals',[B('**Visible vegetation:** infection signs resolved plus ≥2 weeks of negative cultures.','Without vegetations or relevant residual ghosts, the usual minimum framework is ≥72 hours of negative cultures after extraction.'),B('**Reimplant as late as practical**, not automatically on the earliest qualifying day.','Persistent valve/metastatic infection can require further delay.'),B('**Monitor the temporary system and complete antimicrobials.**','Count documented microbiological clearance, not simply time since extraction.')]),
'10-062':S('Require Both Cardiac and Procedural Eligibility',[B('**High-risk cardiac condition + gingival/periapical manipulation or oral-mucosal perforation.**','A prosthetic valve with dental extraction satisfies both; radiography does not meet the procedural criterion.'),B('**Cardiac groups are listed in the table.**','Prosthetic valves include transcatheter valves; pacemaker, isolated bicuspid valve or MVP alone does not qualify.')],
 'Prevention Beyond the Dose',[B('**Use the recommended single dose after allergy review.**','Verify the exact congenital/transplant lesion rather than relying on its broad label.'),B('**Maintain oral hygiene and regular dental care.**','Procedural prophylaxis does not prevent all IE or replace management of other sources; document both eligibility components.')]),
'10-063':S('Single Planned Dose',[B('**Amoxicillin 2 g orally 30–60 minutes before** the qualifying procedure.','If inadvertently missed, a dose within 2 hours afterward is a rescue provision, not preferred planned timing.'),B('**Prophylaxis differs from treating dental infection.**','Routine multiday dosing is unnecessary.')],
 'Route and Allergy Alternatives',[B('**Use the table to choose the single adult dose.**','Clarify the reaction history; avoid specified cephalosporin options after penicillin-associated anaphylaxis, angioedema or urticaria.'),B('**Clindamycin is no longer recommended** for dental IE prophylaxis.','Review macrolide interactions and other patient factors; provide clear timing instructions and ongoing oral-care advice.')]),
'10-064':S('Named Guideline Difference',[B('**AHA:** no IE prophylaxis for elective colonoscopy without active infection solely because of a prosthetic valve.','The same principle covers TEE, GI endoscopy and cystoscopy in that setting.'),B('**ESC 2023:** prophylaxis may be considered for selected high-risk invasive nondental procedures.','Class IIb with limited evidence; not a universal mandate or proven randomized benefit.')],
 'Keep Separate Indications Separate',[B('**Active infection requires treatment and procedure-specific assessment.**','Other procedural prophylaxis indications can exist independently of IE prevention.'),B('**Document the society/framework and individualized rationale.**','Do not combine conflicting recommendations into an unnamed rule; retain asepsis, oral/skin care and prompt fever evaluation.')]),
'10-065':S('Investigate Colorectal Pathology',[B('**S. gallolyticus IE warrants appropriate colon evaluation.**','Lesions may be silent; routine abdominal CT does not replace mucosal assessment.'),B('**Review prior colonoscopy quality and timing.**','Coordinate with recovery, cardiac stability and anticoagulation needs.')],
 'Post-Treatment Follow-Up',[B('**Establish clinical/echo baseline and arrange review.**','Follow residual valve disease and HF; obtain post-treatment cultures as appropriate and investigate new fever promptly.'),B('**Relapse suggests persistent infection; reinfection may involve new exposure or organisms.**','Interpret timing and microbiology together; reinforce dental/skin care and future prophylaxis eligibility.'),B('**AHA 2026 also considers colonoscopy reasonable in E. faecalis IE.**','This is not a universal colonoscopy mandate for every enterococcal blood-culture result.')]),
'10-050':S('Conditional Delay After Hemorrhage',[B('**ESC: consider delaying surgery >1 month when feasible.**','Assess mechanism, volume, evolution, neurological status and meaningful recovery; investigate an infective aneurysm when suspected.'),B('**If deferred, repeat CT/MRI in about 1–2 weeks**, earlier with deterioration.')],
 'Reassess if Cardiac Risk Changes',[B('**Unstable HF, uncontrolled infection or high embolic risk may require earlier surgery.**','Balance hemorrhage expansion against the risk of waiting with neurological and cardiac specialists.'),B('**Earlier-operation evidence is observational and selected.**','Symptom improvement alone does not prove hemorrhage stability; a fixed calendar cannot replace reassessment.'),B('**Treat the neurological cause and review antithrombotics.**','Endovascular aneurysm treatment can change surgical sequencing.')]),
'10-051':S('Define the Vascular Lesion',[B('**Catheter angiography is appropriate after acute hemorrhage with persistent aneurysm suspicion despite negative CTA.**','CTA/MRA are screening tools; a negative screen does not resolve this high-probability presentation.'),B('**Infective aneurysm reflects arterial wall infection.**','The historical term mycotic does not require a fungal pathogen.')],
 'Coordinate Neurovascular and Valve Care',[B('**Ruptured, enlarging or high-risk lesions may require endovascular or surgical treatment plus antibiotics.**','Selected unruptured lesions can undergo specialist surveillance with serial vascular imaging.'),B('**The lesion and its treatment affect valve-surgery timing and antithrombotic decisions.**','This is targeted angiography, not routine invasive screening of asymptomatic IE.')]),
'10-052':S('Recognize an Infected Splenic Focus',[B('**Persistent fever and a large abscess despite active antibiotics require source-control review.**','A sterile infarct differs from secondary infection; drainage versus splenectomy depends on location, loculation, access and risk.')],
 'Sequence Both Interventions',[B('**Consider splenic treatment before valve surgery if cardiac stability permits.**','Reducing a persistent focus may limit dissemination/reinfection; evidence for exact sequencing is limited.'),B('**Emergency valve deterioration can change the order.**','Coordinate cardiac/abdominal surgery, infection and interventional radiology; continue antibiotics and cultures.'),B('**After splenectomy, arrange vaccination and postsplenectomy prevention.**','Document what deterioration would trigger a change in the agreed sequence.')]),
'10-053':S('Interpret the Nephritic Pattern',[B('**Dysmorphic hematuria, red-cell casts, proteinuria and low complement support infection-associated GN.**','ANCA can be positive during IE; it does not independently establish primary vasculitis.'),B('**Other AKI mechanisms can coexist:** embolism, hypoperfusion and drug toxicity.')],
 'Control Infection and Clarify Uncertainty',[B('**Prioritize infection treatment with renal assessment.**','Follow creatinine, proteinuria and sediment; adjust renally cleared drugs and avoid preventable nephrotoxicity.'),B('**Nephrology review/biopsy may help severe, atypical or persistent disease** when results would change management.','Do not initiate high-risk immunosuppression from ANCA alone during active IE.'),B('**Provide dialysis/supportive care when indicated** and assess cardiac source control independently.')]),
'10-054':S('No New Indication From Vegetation Alone',[B('**Do not initiate anticoagulants or antiplatelets solely to prevent septic emboli.**','Treat infection and assess selected surgery; cerebral emboli may coexist with hemorrhage or infective aneurysm.')],
 'Separate Established Indications',[B('**AF, mechanical valves or VTE require individual assessment.**','ESC supports continuing an established indication when contraindications are absent; bleeding, neurological injury, interactions or surgery may change the plan.'),B('**A reversible heparin strategy is sometimes useful perioperatively.**','It is not universal advice during active intracranial bleeding; DOACs cannot replace appropriate mechanical-valve anticoagulation.'),B('**Coronary antiplatelet indications also need separate review.**')]),
'10-055':S('Avoid Routine Systemic Thrombolysis',[B('**IV thrombolysis is not recommended in IE-associated stroke.**','Septic arterial injury, aneurysm and hemorrhagic conversion increase bleeding concern even when initial CT shows no hemorrhage.')],
 'Assess Mechanical Thrombectomy',[B('**Urgent specialist assessment for an eligible large-vessel occlusion.**','Evaluate time, infarct burden, salvageable tissue and prognosis; evidence in IE is less extensive than in ordinary stroke.'),B('**Send retrieved embolic material for pathology/microbiology when feasible.**','Reassess hemorrhage, aneurysm concerns, valve source and surgical timing afterward.'),B('**Do not substitute reflex heparin or exclude all reperfusion.**','Antithrombotic decisions require a separate indication and bleeding-risk review.')]),
'10-044':S('Emergency Valve Failure',[B('**Refractory pulmonary edema or cardiogenic shock from acute regurgitation requires emergency surgery** when nonfutile.','ESC emergency timing is generally within 24 hours; ongoing deterioration warrants immediate action.'),B('**Antibiotics cannot immediately repair valve destruction.**')],
 'Parallel Stabilization',[B('**Resuscitation, antimicrobials and operative preparation proceed together.**','Tailor support to valve physiology and perfusion; obtain cultures and essential imaging without harmful delay.'),B('**Urgent 3–5-day timing applies to less catastrophic indications.**','Neither a minimum preoperative antibiotic period nor culture clearance overrides mechanical shock.')]),
'10-045':S('Conduction Disease Signals Extension',[B('**New AV block plus an enlarging periannular abscess indicates local progression.**','The aortic annulus lies near the conduction system; bloodstream clearance does not establish anatomical cure.'),B('**TEE and selected cardiac CT define extent.**','Monitor rhythm and provide temporary pacing when needed.')],
 'Source Control and Rhythm Safety',[B('**Urgent surgical assessment**, usually within 3–5 days and sooner if physiology requires.','An enlarging abscess with high-grade block does not fit conservative surveillance of a small controlled lesion.'),B('**Pacing treats bradycardia, not infected tissue.**','Coordinate surgery, infection and electrophysiology teams; consider active infection when choosing device timing and platform.')]),
'10-046':S('Verify Persistent Infection',[B('**Bacteremia beyond about one treatment week despite adequate therapy and excluded other sources warrants urgent surgical review.**','Confirm organism, susceptibility, dosing, delivery and relevant concentrations.'),B('**Positive cultures at 48–72 hours already prompt intensified assessment.**','Do not wait a week to investigate lines, implants or metastatic foci.')],
 'Identify Failure of Source Control',[B('**Repeat imaging for abscess, vegetation progression, dehiscence or valve dysfunction.**','Persistent shock can accelerate intervention when surgery is nonfutile.'),B('**Separate fever from bacteremia.**','Drug fever or embolic inflammation can cause temperature, but neither explains repeated viable blood cultures.'),B('**Continue active therapy while arranging source control**, without unsupported antifungal escalation.')]),
'10-047':S('Embolic Events Plus Vegetation',[B('**Recurrent systemic embolism despite treatment with a mobile 14-mm mitral vegetation supports urgent surgery review.**','Integrate size, mobility, location, organism and response; assess neurological injury and operative risk.')],
 'Interpret Thresholds in Context',[B('**ESC uses ≥10 mm in several left-sided recommendations with different strengths and contexts.**','An isolated lesion without embolism or severe dysfunction is a more discretionary decision.'),B('**Do not wait for 20 mm or severe HF in this recurrent-embolism scenario.**','Early antibiotics reduce but do not immediately eliminate embolic risk.'),B('**Anticoagulation is not a substitute for infection/source treatment.**','Review any separate anticoagulation indication against bleeding and neurological risks.')]),
'10-048':S('EASE Design',[B('**76 selected left-sided native-valve IE patients** randomized to early surgery or conventional management.','Early surgery occurred within 48 hours; conventional management could also include subsequent surgery.')],
 'Outcome and Applicability',[B('**In-hospital death or embolism within 6 weeks: approximately 3% versus 23%.**','The benefit was driven mainly by fewer systemic emboli; isolated six-month mortality reduction was not established.'),B('**A composite benefit does not prove every component.**','Do not extrapolate directly to frail prosthetic cases or describe EASE as a cardiogenic-shock rescue trial.'),B('**Integrate embolic prevention with HF, uncontrolled infection and operative risk.**','Appropriate antibiotics remain necessary whichever surgical strategy is selected.')]),
'10-049':S('Assess the Stroke Before Setting Timing',[B('**Small nonhemorrhagic ischemic stroke does not mandate a fixed surgical delay.**','Assess infarct burden, consciousness, hemorrhage and expected recovery; TIA generally does not delay indicated surgery.')],
 'Balance Neurological and Cardiac Risk',[B('**Proceed with indicated urgent surgery after multidisciplinary assessment** when abscess/uncontrolled infection persists, coma is absent and hemorrhage is excluded.','A large infarction with poor neurological status requires a different assessment.'),B('**Waiting also carries risk:** abscess progression, HF and recurrent emboli.','Review hemorrhagic conversion and suspected infective aneurysm; use repeat/vascular imaging when indicated.'),B('**Exact timing evidence is mainly observational.**','Document neurological prognosis and the cardiac reason for urgency.')]),
'10-038':S('AHA 2026 Postoperative Duration',[B('**Credit effective preoperative treatment; give ≥14 postoperative days** when surgery occurs before treatment completion.','Five preoperative weeks plus only seven postoperative days would miss that minimum.'),B('**Positive valve culture/PCR alone does not restart a full course.**','This differs from ESC 2023; molecular signal can persist without viable organisms.')],
 'Individualize the Endpoint',[B('**Residual abscess, metastatic infection or unusual pathogens may require longer therapy.**','Evidence for exact postoperative duration is mainly observational; review with the Endocarditis Team.'),B('**A completed course before later surgery without active infection is a different situation.**','Additional antibiotics may then be unnecessary; fungal IE also has a separate framework.'),B('**Document treatment history, source control and completion date.**')]),
'10-039':S('POET Eligibility',[B('**Stable selected left-sided bacterial IE after effective initial IV treatment.**','Studied organisms: streptococci, E. faecalis, S. aureus and coagulase-negative staphylococci.','At least 10 IV-treatment days preceded randomization; postoperative and other stability requirements also applied.'),B('**Verify clearance, controlled complications, absorption, adherence and follow-up.**','Do not extrapolate to persistent bacteremia, uncontrolled abscess, MRSA, fungi or non-HACEK Gram-negative IE.')],
 'Trial Interpretation',[B('**400 participants; six-month composite: IV 12.1%, oral 9.0%.**','The composite comprised death, unplanned cardiac surgery, embolism or relapse; the selected strategy met noninferiority.'),B('**Oral completion does not shorten the intended total course.**','The result supports a monitored combination strategy, not any convenient oral drug or automatic discharge after day 10.')]),
'10-040':S('Choose an Evidence-Based Oral Combination',[B('**Two active oral agents selected by organism and susceptibility.**','Review expected exposure, renal/hepatic adjustment, food/cation interactions and absorption.'),B('**Use validated pathogen-specific doses.**','The same drug name does not guarantee equivalent oral and IV exposure.')],
 'Arrange Monitoring Before Transition',[B('**Confirm access, adherence, laboratory checks and rapid return to care.**','Rifampin: enzyme-induction interactions; linezolid: cytopenias/neuropathy; fluoroquinolones: QT/tendon and other risks.'),B('**Recurrent fever, HF, neurological symptoms or bacteremia prompts reassessment.**','Check adherence, resistance and uncontrolled infection; oral treatment does not cancel indicated source control.'),B('**Complete the planned adequate course** with scheduled follow-up.')]),
'10-041':S('DOTS Population and Regimen',[B('**Completion after clearance in selected complicated S. aureus bacteremia.**','Included some right-sided IE; excluded left-sided IE, retained infected prosthetic material, CNS infection and severe immunocompromise.'),B('**200 participants; dalbavancin 1500 mg IV on days 1 and 8**, with trial-specified renal adjustment when needed.')],
 'Evidence Boundary',[B('**Primary superiority analysis was not positive.**','Secondary noninferiority findings must not be relabeled as proof of universal superiority.'),B('**IE use remains off-label and selected.**','Confirm susceptibility, clearance, source control, stability and follow-up.'),B('**Long half-life reduces line needs but limits rapid drug withdrawal.**','Convenience does not establish efficacy in excluded left-sided or retained-prosthesis infection.')]),
'10-042':S('Restricted ESC Short Course',[B('**Two weeks of oxacillin/cloxacillin** for a fully assessed uncomplicated right-sided MSSA phenotype.','Normal-organ-function adult example: 2 g IV every 4 hours.'),B('**Eligibility:** prompt response, vegetation ≤20 mm, no prosthesis, left-sided infection, severe immunosuppression or important metastatic/pleural/cardiac complication.')],
 'When to Use a Longer Course',[B('**Usually 4–6 weeks outside this narrow setting or with another agent.**','Cefazolin, vancomycin and daptomycin do not automatically inherit the short oxacillin/cloxacillin evidence.'),B('**Gentamicin is not routinely required.**','Continue cultures and reassess slow response or new focal symptoms.'),B('**Provide addiction care and reliable treatment delivery.**','Confirm absence of left-sided disease by adequate imaging, not pulmonary symptoms alone.')]),
'10-043':S('Treat the Original NVE Episode',[B('**Replacement during NVE treatment does not itself create PVE.**','Continue the appropriate NVE regimen unless new microbiological or anatomical findings require change.'),B('**For MSSA, retain a suitable antistaphylococcal beta-lactam.**','New hardware alone does not justify routine rifampin or gentamicin.')],
 'Review Operative Findings',[B('**Integrate culture clearance, operative results and residual/metastatic infection.**','A negative treated valve culture does not establish that systemic therapy is complete.'),B('**Document the remaining course and monitoring.**','Assess drug toxicity, postoperative valve function and relapse; a later genuine prosthetic infection requires its own evidence.')]),
}
